import pathlib
p = pathlib.Path('src/types/stream_constants.rs')
t = p.read_text()
old = '''pub(crate) use elephc_builtin_contract::php_constants::{
    STREAM_SERVER_BIND, STREAM_SERVER_DEFAULT_FLAGS, STREAM_SERVER_LISTEN,
};'''
new = '''// \`STREAM_SERVER_BIND\` is declared beside these but named only in prose here, so it is not
// re-exported: the compiler reads it through the constant table like any other php constant.
pub(crate) use elephc_builtin_contract::php_constants::{
    STREAM_SERVER_DEFAULT_FLAGS, STREAM_SERVER_LISTEN,
};'''
assert t.count(old) == 1
p.write_text(t.replace(old, new, 1))
print('re-export narrowed to what elephc names')
